with flattened as (select id, effective_from, explode_outer(discounts) as tier_value from price_tiers) select id, effective_from, tier_value, dense_rank() over (order by tier_value desc) as tier_value_dense_rank, sum(tier_value) over (partition by month(effective_from)) as effective_from_month_sum_tier_value, rank() over w_recent as tier_value_rank from flattened window w_recent as (order by tier_value)
